#!/usr/bin/env bash
# Hub lane (R10) art draws: the home level map. ONE at a time via studio/bin/art.sh. usage: hub.sh [name...]
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run map_bg && g map_bg "Portrait 2:3 full-bleed game background, NO magenta. A cozy cat-cafe town garden seen from straight above like a mobile puzzle saga map: soft sage and fresh green lawn with gentle mounds, tiny daisies and clover patches, a few small round bushes and flower clusters scattered only near the left and right edges, a couple of flat round stepping stones, small paw prints pressed into the grass here and there. The whole centre is open calm grass with no path and no road, no buildings, no characters, no cats. Even soft lighting, low contrast so game buttons read on top of it. $S"
run map_nodes && g map_nodes "Four game map pieces seen slightly from above: 1) a wooden signpost on a short post whose sign board is a wide blank honey oak plank with two little cat ears on its top edge, empty board, 2) a round puffy cream felt cushion like a big cookie with a stitched rim and a flat empty centre, 3) the same round cushion in glowing warm honey gold with a soft sparkle rim and a flat empty centre, 4) the same round cushion in dusty lilac grey with a small brass padlock at the bottom edge. $G 2 columns by 2 rows in that order. $K $S"
run map_props && g map_props "Six small garden props for a cat town map: a terracotta pot with a leafy fern, a wicker basket holding two yarn balls, a little black iron street lamp with a warm glow, a round pink flower bush, a blue cat food bowl with a fish bone, a red wooden mailbox on a post. $G 3 columns by 2 rows. $K $S"
